import { AbstractControl, ValidationErrors } from '@angular/forms';
import { Observable } from 'rxjs';
import { AllUnits, RobotSettings, SymbolService, ValueObjectMap, ValueRange } from '@universal-robots/contribution-api';
import { URValidationResponse, URValidatorFn } from '@universal-robots/ui-models';
import { converter, FixedPointNumber, Unit, Units, UnitType } from '@universal-robots/utilities-units';

/**
 * Represents a custom validation error object that extends Angular's `ValidationErrors`.
 * This type allows for additional flexibility by supporting custom error keys translation keys.
 *
 * @typedef {InternalURValidationErrors}
 * @keys {string} - The error key, which is a string representing translationKey of the error.
 * @property {string | boolean | { interpolateParams?: object }} [key: string] - Custom error keys with their associated values.
 * - `string`: A descriptive error message translated by consumer.
 * - `boolean`: A flag indicating the presence of the error.
 * - `{ interpolateParams?: object }`: Optional parameters for message interpolation (e.g., for translations).
 *
 * Example:
 * ```typescript
 * const errors: URValidationErrors = {
 *   'validation.required': true,
 *   'validation.maxLength': { interpolateParams: { maxLength: 10 } },
 *   'validation.customError': "This is a custom error message."
 * };
 * ```
 */
type InternalURValidationErrors = ValidationErrors & {
    [key: string]: string | boolean | { interpolateParams?: object };
};
type InternalURValidationResponse = InternalURValidationErrors | URValidationResponse;
type InternalURValidatorFn =
    | URValidatorFn
    | ((
          control: AbstractControl,
      ) => InternalURValidationResponse | Promise<InternalURValidationResponse> | Observable<InternalURValidationResponse>);
const lengthValidator =
    (
        options: { maxLength?: number; minLength?: number; maxDecimalLength?: number; unit?: Unit },
        errorMessages: { maxLength?: string; minLength?: string; maxDecimalLength?: string } = {},
    ): InternalURValidatorFn =>
    (control): InternalURValidationErrors | null => {
        const valueAsString = control?.value?.toString();
        if (valueAsString === undefined) {
            return null;
        }
        if (typeof options.maxLength === 'number' && valueAsString.length > options.maxLength) {
            return {
                'validation.maxLength': errorMessages.maxLength || { interpolateParams: { maxLength: options.maxLength } },
            };
        }
        if (typeof options.minLength === 'number' && valueAsString.length < options.minLength) {
            return {
                'validation.minLength': errorMessages.minLength || { interpolateParams: { minLength: options.minLength } },
            };
        }
        if (options.maxDecimalLength || options.unit) {
            const maxDec = options.maxDecimalLength ?? options.unit?.significantDigits;
            const number = valueAsString.split('.')[1] || '';
            if (maxDec && number.length > maxDec) {
                return {
                    'validation.maxDecimalLength': errorMessages.maxDecimalLength || {
                        interpolateParams: { maxDecimalLength: maxDec },
                    },
                };
            }
        }

        return null;
    };
export const createLengthValidator = lengthValidator as (options: {
    maxLength?: number;
    minLength?: number;
    maxDecimalLength?: number;
    unit?: Unit;
}) => URValidatorFn;

const rangeValidator =
    (
        options: { maxValue?: number; minValue?: number; unit?: string },
        errorMessages: { maxValue?: string; minValue?: string } = {},
    ): InternalURValidatorFn =>
    (control): InternalURValidationResponse => {
        if (typeof options.maxValue === 'number' && control.value > options.maxValue) {
            return {
                'validation.maxValue': errorMessages.maxValue || { interpolateParams: { maxValue: options.maxValue, unit: options.unit } },
            };
        }
        if (typeof options.minValue === 'number' && control.value < options.minValue) {
            return {
                'validation.minValue': errorMessages.minValue || { interpolateParams: { minValue: options.minValue, unit: options.unit } },
            };
        }
        return null;
    };

export const createRangeValidator = rangeValidator as (options: { maxValue?: number; minValue?: number; unit?: string }) => URValidatorFn;

const variableNameValidator = (
    symbolService: SymbolService,
    errorMessages: {
        variableNameEmpty?: string;
        variableNameTooLong?: string;
        variableNameInvalid?: string;
        alreadyExists?: string;
    } = {},
    ownVariableName?: string,
): InternalURValidatorFn => {
    return async (control: AbstractControl): Promise<InternalURValidationResponse> => {
        if (!control.value) {
            return {
                'validation.variable.empty': errorMessages.variableNameEmpty || true,
            };
        }
        if (control.value.length > 1024) {
            return {
                'validation.variable.maxLength': errorMessages.variableNameTooLong || { interpolateParams: { maxLength: 1024 } },
            };
        }
        if (!isValidSymbolName(control.value)) {
            return {
                'validation.variable.invalid': errorMessages.variableNameInvalid || true,
            };
        }
        if (control.value !== ownVariableName && (await symbolService.isRegisteredVariableName(control.value))) {
            return {
                'validation.variable.alreadyExists': errorMessages.alreadyExists || true,
            };
        }

        return null;
    };
};
export const createVariableNameValidator = variableNameValidator as (
    symbolService: SymbolService,
    errorMessages?: {
        variableNameEmpty?: string;
        variableNameTooLong?: string;
        variableNameInvalid?: string;
        variableNameNotRegistered?: string;
    },
) => URValidatorFn;

const functionNameValidator = (symbolService: SymbolService, ownFunctionName: string, moduleName: string): InternalURValidatorFn => {
    return async (control: AbstractControl) => {
        if (!control.value) {
            return { 'validation.function.empty': true };
        }
        if (!isValidSymbolName(control.value)) {
            return { 'validation.function.invalid': true };
        }
        if (control.value !== ownFunctionName && (await symbolService.isRegisteredFunctionName(control.value, moduleName))) {
            return { 'validation.function.exists': true };
        }
        return null;
    };
};
export const createFunctionNameValidator = functionNameValidator as (
    symbolService: SymbolService,
    ownFunctionName: string,
    moduleName: string,
) => URValidatorFn;

export const moduleNameValidator = (symbolService: SymbolService, ownModuleName: string): InternalURValidatorFn => {
    return async (control) => {
        if (!control.value) {
            return { 'validation.module.empty': true };
        }
        if (!isValidSymbolName(control.value)) {
            return { 'validation.module.invalid': true };
        }
        if (control.value !== ownModuleName && (await symbolService.isRegisteredModuleName(control.value))) {
            return { 'validation.module.exists': true };
        }
        return null;
    };
};
export const createModuleNameValidator = moduleNameValidator as (symbolService: SymbolService, ownModuleName: string) => URValidatorFn;

const numberValidator = (minValue: number, maxValue: number, unit: string, robotSettings: RobotSettings): InternalURValidatorFn => {
    return (control) => {
        const units = robotSettings.units;
        // ValueObjectMap expects AllUnits as key, but unit is string
        const valueObjectUnit = ValueObjectMap[unit as AllUnits];
        const significantDigits = units[valueObjectUnit.quantity.quantity].significantDigits;
        const lowerLimit = converter(new FixedPointNumber(minValue, valueObjectUnit), units[valueObjectUnit.quantity.quantity]);
        const upperLimit = converter(new FixedPointNumber(maxValue, valueObjectUnit), units[valueObjectUnit.quantity.quantity]);
        const scale = 10 ** significantDigits;

        if (!isValueWithinLimits(control.value, lowerLimit.getValue(), upperLimit.getValue(), scale)) {
            return {
                'validation.range-error': {
                    interpolateParams: {
                        minValue: createMinString(lowerLimit, scale),
                        maxValue: createMaxString(upperLimit, scale),
                    },
                },
            };
        } else {
            return null;
        }
    };
};
export const createNumberValidator = numberValidator as (
    minValue: number,
    maxValue: number,
    unit: string,
    robotSettings: RobotSettings,
) => URValidatorFn;

const numberRangeValidator = (valueRange: ValueRange, units: Units): InternalURValidatorFn => {
    return numberValidator(valueRange.min, valueRange.max, valueRange.unit, { language: '', units });
};
export const createNumberRangeValidator = numberRangeValidator as (valueRange: ValueRange, units: Units) => URValidatorFn;

export const createExpressionValidator = (minLength?: number, maxLength?: number): InternalURValidatorFn => {
    return (control) => {
        const value = control.value?.trim() ?? '';
        if (minLength !== undefined && value.length < minLength) {
            return { 'validation.expression.tooShort': { requiredLength: minLength, actualLength: value.length } };
        }
        if (maxLength !== undefined && value.length > maxLength) {
            return { 'validation.expression.tooLong': { requiredLength: maxLength, actualLength: value.length } };
        }
        return null;
    };
};
/**
 * Test for integer numbers to insure whole numbers
 * @example
 * ```
 *  integerValidator({valie: 1.2}) // false
 *  integerValidator({value: 1}) // true
 * ```
 */
const integerValidator = (): InternalURValidatorFn => (control: AbstractControl) => {
    const value = control.value;
    if (value === null || value === undefined || value.toString() === '') {
        return null; // Let required validator handle empty values
    }
    if (!Number.isInteger(value)) {
        return { 'validation.integer': true };
    }
    return null;
};
export const createIntegerValidator = integerValidator as () => URValidatorFn;

/**
 * Helper Functions
 */

function ceilAndScale(lowerLimit: number, scale: number) {
    return Math.ceil(lowerLimit * scale) / scale;
}

function floorAndScale(upperLimit: number, scale: number) {
    return Math.floor(upperLimit * scale) / scale;
}

function isValueWithinLimits(val: number, lowerLimit: number, upperLimit: number, scale: number) {
    return val >= ceilAndScale(lowerLimit, scale) && val <= floorAndScale(upperLimit, scale);
}

function createMinString(lowerLimit: FixedPointNumber<UnitType>, scale: number) {
    return `${ceilAndScale(lowerLimit.getValue(), scale)} ${lowerLimit.getUnit().symbol}`;
}

function createMaxString(upperLimit: FixedPointNumber<UnitType>, scale: number) {
    return `${floorAndScale(upperLimit.getValue(), scale)} ${upperLimit.getUnit().symbol}`;
}

function isValidSymbolName(name?: string): boolean {
    if (!name) {
        return false;
    }
    return /^[a-zA-Z]+\w*$/.test(name);
}
